import { createHmac } from "crypto";

export class PaddleSignatureVerifier {

private secretKey: string;

```
constructor(secretKey: string) {
    if (!secretKey) {
        throw new Error("A secret key is required to initialize PaddleSignatureHandler.");
    }
    this.secretKey = secretKey;
}

/**
 * Parse the Paddle-Signature header to extract timestamp and signature.
 * @param headerSignature - The Paddle-Signature header string.
 * @returns An object containing the timestamp and signature.
 */
parseSignatureHeader(headerSignature: string): { timestamp: string; signature: string } | null {
    if (!headerSignature) {
        return null;
    }

    const elements = headerSignature.split(";");
    const parsed: Record<string, string> = {};

    for (const element of elements) {
        const [key, value] = element.split("=").map((str) => str.trim());
        if (key && value) {
            parsed[key] = value;
        }
    }

    const timestamp = parsed["ts"];
    const signature = parsed["h1"];

    if (!timestamp || !signature) {
        return null;
    }

    return {
        timestamp,
        signature,
    };
}

/**
 * Build the signed payload by concatenating the timestamp and raw body.
 * @param timestamp - The extracted timestamp.
 * @param rawBody - The raw body of the request.
 * @returns The signed payload string.
 */
buildSignedPayload(timestamp: string | number, rawBody: string): string {
    if (!timestamp || !rawBody) {
        throw new Error("Both timestamp and raw body are required to build the signed payload.");
    }

    if (typeof rawBody !== 'string') {
        throw new Error('Raw body must be a string');
    }

    return `${timestamp}:${rawBody}`;
}

/**
 * Hash the signed payload using HMAC with SHA256 and the secret key.
 * @param signedPayload - The signed payload string.
 * @returns The HMAC-SHA256 hash as a hexadecimal string.
 */
hashSignedPayload(signedPayload: string): string {
    if (!signedPayload) {
        throw new Error("Signed payload is required to compute the hash.");
    }

    const hmac = createHmac("sha256", this.secretKey);
    hmac.update(signedPayload);
    return hmac.digest("hex");
}

