For anyone using python sdk here is the equivalent python code for manual verification written by [@temtechie](https://github.com/temtechie)

```
import hmac
import hashlib
from typing import Optional, Dict, Tuple

class PaddleSignatureVerifier:
    def __init__(self, secret_key: str):
        if not secret_key:
            raise ValueError("A secret key is required to initialize PaddleSignatureHandler.")
        self.secret_key = secret_key

    def parse_signature_header(self, header_signature: str) -> Optional[Dict[str, str]]:
        """Parse the Paddle-Signature header to extract timestamp and signature."""
        if not header_signature:
            return None

        elements = header_signature.split(";")
        parsed = {}

        for element in elements:
            key_value = element.strip().split("=", 1)
            if len(key_value) == 2:
                key, value = key_value
                parsed[key.strip()] = value.strip()

        timestamp = parsed.get("ts")
        signature = parsed.get("h1")

        if not timestamp or not signature:
            return None

        return {
            "timestamp": timestamp,
            "signature": signature
        }

    def build_signed_payload(self, timestamp: str, raw_body: str) -> str:
        """Build the signed payload by concatenating the timestamp and raw body."""
        if not timestamp or not raw_body:
            raise ValueError("Both timestamp and raw body are required to build the signed payload.")

        if not isinstance(raw_body, str):
            raise ValueError("Raw body must be a string")

        return f"{timestamp}:{raw_body}"

    def hash_signed_payload(self, signed_payload: str) -> str:
        """Hash the signed payload using HMAC with SHA256 and the secret key."""
        if not signed_payload:
            raise ValueError("Signed payload is required to compute the hash.")

        hmac_obj = hmac.new(
            self.secret_key.encode('utf-8'),
            signed_payload.encode('utf-8'),
            hashlib.sha256
        )
        return hmac_obj.hexdigest()

    def verify_signature(self, header: str, raw_body: str) -> bool:
        """Verify the Paddle-Signature header against the raw request body."""
        parsed_header = self.parse_signature_header(header)
        if not parsed_header:
            return False

        timestamp = parsed_header["timestamp"]
        signature = parsed_header["signature"]
        signed_payload = self.build_signed_payload(timestamp, raw_body)
        computed_signature = self.hash_signed_payload(signed_payload)

        return computed_signature == signature

    def parse_raw_body(self, header: str, raw_body: str) -> dict:
        """Parse the raw body to a dict after verifying the signature."""
        is_valid = self.verify_signature(header, raw_body)
        if not is_valid:
            raise ValueError("Invalid signature. The raw body cannot be trusted.")

        try:
            return json.loads(raw_body)
        except json.JSONDecodeError:
            raise ValueError("Failed to parse the raw body. Ensure it is a valid JSON string.")

@router.post("/webhook")
async def handle_webhook(request: Request):
    try:
        # Get the raw body and signature
        raw_body = await request.body()
        body_str = raw_body.decode("utf-8")
        paddle_signature = request.headers.get("paddle-signature")

        if not paddle_signature:
            log.error("Paddle signature missing in header")
            raise HTTPException(
                status_code=400, detail="Missing paddle-signature header"
            )

        # Verify the signature
        webhook_secret = os.getenv("PADDLE_WEBHOOK_SECRET")
        verifier = PaddleSignatureVerifier(webhook_secret)

        try:
            event_data = verifier.parse_raw_body(paddle_signature, body_str)
            log.info(f"Received webhook event: {event_data}")
        except ValueError as e:
            log.error(f"Signature verification failed: {str(e)}")
            raise HTTPException(status_code=401, detail="Invalid webhook signature")

        event_handlers = {
            "subscription.updated": handle_subscription_update,
            "subscription.canceled": handle_subscription_cancellation,
            "subscription.payment_succeeded": handle_payment_success,
            "subscription.payment_failed": handle_payment_failure,
        }

        event_type = event_data.get("event_type")
        if event_type not in event_handlers:
            log.warning(f"Unhandled webhook event type: {event_type}")
            return {"received": True, "handled": False}

        try:
            await event_handlers[event_type](event_data.get("data", {}))
            log.info(f"Successfully processed webhook event: {event_type}")
            return {"received": True, "handled": True}
        except Exception as handler_error:
            log.error(
                f"Error in webhook handler for {event_type}: {str(handler_error)}"
            )
            raise HTTPException(
                status_code=500, detail=f"Webhook handler failed: {str(handler_error)}"
            )

    except json.JSONDecodeError as e:
        log.error(f"Invalid JSON in webhook request: {str(e)}")
        raise HTTPException(status_code=400, detail="Invalid JSON payload")
    except Exception as e:
        log.error(f"Webhook processing failed: {str(e)}")
        raise HTTPException(
            status_code=500, detail=f"Webhook processing failed: {str(e)}"
        )
